---next.config
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  basePath: process.env.BASEPATH,
  redirects: async () => {
    return [
      {
        source: '/',
        destination: '/home',
        permanent: true,
        locale: false
      }
    ]
  },
  output: 'standalone'

  // experimental: {
  //   viewTransition: true
  // }
}

export default nextConfig
---route-handler
import { NextResponse, type NextRequest } from 'next/server'

import { apiServer } from './server'
import type { ApiResponse } from '@/types/common'

/**
 * Thin-proxy route-handler factory. Collapses the repeated
 * `try { const res = await apiServer.x(...); return NextResponse.json(...) } catch {...}`
 * boilerplate in `src/app/api/**` into one-liners that forward to the upstream API
 * via apiServer and return its envelope verbatim, mapping a failed envelope to a
 * 4xx so apiClient's throw-on-!ok behavior keeps working.
 *
 * `buildPath` is either a static upstream path or a function of the dynamic route
 * params (e.g. `({ id }) => `/v1/users/${id}``).
 */
type Ctx<P> = { params: Promise<P> }
type PathBuilder<P> = string | ((params: P) => string)

function respond<T>(res: ApiResponse<T>) {
  return NextResponse.json(res, { status: res.success === false ? 400 : 200 })
}

function resolvePath<P>(buildPath: PathBuilder<P>, params: P): string {
  return typeof buildPath === 'function' ? buildPath(params) : buildPath
}

async function readParams<P>(ctx?: Ctx<P>): Promise<P> {
  return ctx?.params ? await ctx.params : ({} as P)
}

export function proxyGet<T, P = Record<string, string>>(
  buildPath: PathBuilder<P>,
  options: { forwardQuery?: boolean } = {}
) {
  return async (req: NextRequest, ctx?: Ctx<P>) => {
    const params = await readParams(ctx)
    const query = options.forwardQuery ? Object.fromEntries(new URL(req.url).searchParams) : undefined

    return respond(await apiServer.get<T>(resolvePath(buildPath, params), { params: query }))
  }
}

export function proxyPost<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
  return async (req: NextRequest, ctx?: Ctx<P>) => {
    const params = await readParams(ctx)
    const body = await req.json()

    return respond(await apiServer.post<T>(resolvePath(buildPath, params), body))
  }
}

export function proxyPut<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
  return async (req: NextRequest, ctx?: Ctx<P>) => {
    const params = await readParams(ctx)
    const body = await req.json()

    return respond(await apiServer.put<T>(resolvePath(buildPath, params), body))
  }
}

export function proxyDelete<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
  return async (_req: NextRequest, ctx?: Ctx<P>) => {
    const params = await readParams(ctx)

    return respond(await apiServer.delete<T>(resolvePath(buildPath, params)))
  }
}
---server
import { getServerSession } from 'next-auth'

import { authOptions } from '@/libs/auth'
import { createFetcher } from './base-fetcher'

// Server fetcher: reads the session via getServerSession() and returns a typed
// `{ success: false }` envelope on non-OK (callers check `success` rather than
// catching).
export const apiServer = createFetcher({
  baseURL: process.env.NEXT_PUBLIC_API_URL ?? '',
  getSession: () => getServerSession(authOptions),
  onError: async res => {
    const error = await res.json().catch(() => ({
      success: false,
      code: 'ERROR',
      message: res.statusText,
      data: null
    }))

    return {
      success: false,
      code: error.code ?? 'ERROR',
      message: error.message ?? 'Something went wrong',
      data: null
    }
  }
})
