import type { Session } from 'next-auth'

import type { ApiResponse } from '@/types/common'

export type RequestOptions = RequestInit & {
  params?: Record<string, string>
}

type FetcherConfig = {
  baseURL: string

  /** Browser uses getSession(); server uses getServerSession(authOptions). */
  getSession: () => Promise<Session | null>

  /**
   * How a non-OK response is handled. The browser fetcher throws (so mutation
   * hooks surface the message via onError); the server fetcher returns a
   * `{ success: false }` envelope. Either way the return type is the envelope.
   */
  onError: (res: Response) => Promise<ApiResponse<unknown>>
}

/**
 * Shared fetcher core for both apiClient (browser) and apiServer (RSC / route
 * handlers). The only differences between them — session source and error
 * handling — are injected via config; everything else (header building, URL
 * building, the verb wrappers) lives here so the two stay in lockstep.
 */
export function createFetcher({ baseURL, getSession, onError }: FetcherConfig) {
  async function getHeaders(customHeaders?: HeadersInit): Promise<HeadersInit> {
    const session = await getSession()

    return {
      'Content-Type': 'application/json',
      ...(session?.accessToken && {
        Authorization: `Bearer ${session.accessToken}`
      }),
      ...customHeaders
    }
  }

  function buildURL(path: string, params?: Record<string, string>): string {
    // apiClient's baseURL is a same-origin relative prefix ('/api'); resolve it
    // against the browser origin. apiServer's baseURL is already absolute, so the
    // base is ignored there (and window is undefined on the server anyway).
    const base = typeof window === 'undefined' ? undefined : window.location.origin
    const url = new URL(`${baseURL}${path}`, base)

    if (params) {
      Object.entries(params).forEach(([k, v]) => url.searchParams.set(k, v))
    }

    return url.toString()
  }

  async function request<T>(path: string, options: RequestOptions = {}): Promise<ApiResponse<T>> {
    const { params, headers, ...rest } = options

    const res = await fetch(buildURL(path, params), {
      ...rest,
      headers: await getHeaders(headers)
    })

    if (!res.ok) {
      return onError(res) as Promise<ApiResponse<T>>
    }

    return res.json() as Promise<ApiResponse<T>>
  }

  return {
    get: <T>(path: string, options?: RequestOptions) => request<T>(path, { ...options, method: 'GET' }),
    post: <T>(path: string, body: unknown, options?: RequestOptions) =>
      request<T>(path, { ...options, method: 'POST', body: JSON.stringify(body) }),
    put: <T>(path: string, body: unknown, options?: RequestOptions) =>
      request<T>(path, { ...options, method: 'PUT', body: JSON.stringify(body) }),
    delete: <T>(path: string, options?: RequestOptions) => request<T>(path, { ...options, method: 'DELETE' })
  }
}

