def warn(msg):
    print("WARN:", msg, file=sys.stderr)

# ── 1. Advisory lock (script-held; vault-core.md §Concurrency contract) ──
fd = None
for attempt in range(4):
    try:
        fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        os.write(fd, str(os.getpid()).encode())
        break
    except FileExistsError:
        if attempt < 3:
            time.sleep((0.1, 0.5, 1.5)[attempt])
if fd is None:
    try:
        holder = open(lock_path, encoding="utf-8", errors="replace").read().strip() or "unknown"
    except Exception:
        holder = "unknown"
    print(f"FAIL: {lock_path} held after 3 backoff retries (holder pid: {holder}). "
          f"Another mega-sdd writer is updating vault.json. If NO concurrent run is "
          f"active and the lock mtime is >30s old it is orphaned — rm the lock file "
          f"and re-run.", file=sys.stderr)
    sys.exit(4)

try:
    # ── 2. Read the docs + parse (errors → exit 2, fs untouched) ──
    docs = {}
    for fn in DOCS:
        p = os.path.join(vault, fn)
        if os.path.isfile(p):
            docs[fn] = open(p, encoding="utf-8", errors="replace").read()

    errors = []
    if LAYOUT2:
        # Hard section-header contract (gate addition 2): DOC_CODE re-keys
        # from filename to section, so a missing anchor header must FAIL
        # loud here — never a silently empty derivation.
        for h in vault_md.v2_missing_headers(docs.get("vault.md", "")):
            errors.append(
                f"vault.md is missing the mandatory section header `{h}` "
                f"(layout-2 hard-header contract — the section anchors "
                f"replace the legacy per-file identity)"
            )
    entities = vault_md.parse_data_model(docs.get(DOC_DM, ""), errors,
                                         doc_name=DOC_DM)
    flows = vault_md.parse_flows(docs.get(DOC_FL, ""), errors, doc_name=DOC_FL)
    adrs = vault_md.parse_adrs(docs.get(DOC_DC, ""), errors, doc_name=DOC_DC)
    skeletons = []
    seen_tags = {}
    for fn in OQ_DOCS:
        for oq in vault_md.parse_open_questions(fn, docs.get(fn, ""), errors):
            if oq["tag"] in seen_tags:
                errors.append(
                    f"duplicate OQ tag across docs: {oq['tag']} "
                    f"({seen_tags[oq['tag']]} and {fn})"
                )
                continue
            seen_tags[oq["tag"]] = fn
            skeletons.append(oq)
    if LAYOUT2:
        # OQs are constraints.md-owned on layout-2. A checkbox OQ line in any
        # OTHER doc would be silently invisible to the universe — fail loud.
        for fn in DOCS:
            if fn in OQ_DOCS:
                continue
            for line in docs.get(fn, "").splitlines():
                if re.match(r"^-\s*\[", line) and vault_md.OQ_TAG_RE.search(line):
                    errors.append(
                        f"OQ checkbox line found in {fn} — layout-2 centralizes "
                        f"ALL Open Questions in constraints.md `## Open "
                        f"Questions` (move the line there; use `[origin: "
                        f"<file>#<anchor>]` to keep its locality)"
                    )
                    break
    # 6.0.1 F5: md-hint fallback for the five patch-lane OQ fields — collected
    # per doc, applied LAST in the per-OQ merge (setdefault only; patch and
    # prior carry-forward always win)
    md_hints = {}
    for fn in OQ_DOCS:
        for t, fields in vault_md.parse_oq_field_hints(docs.get(fn, "")).items():
            md_hints.setdefault(t, {}).update(
                {k: v for k, v in fields.items() if k not in md_hints.get(t, {})})
    # roll-up category fallback is a LEGACY-only surface (layout-2 has no
    # roll-up — bracket-first is the primary contract there)
    rollup_cats = ({} if LAYOUT2
                   else vault_md.parse_rollup_categories(docs[DOC_INDEX]))
    for oq in skeletons:
        if not oq.get("category") and oq["tag"] in rollup_cats:
            # bracket-first precedence; legacy fallback = roll-up header text
            oq["category"] = rollup_cats[oq["tag"]]
    lock_vals = vault_md.parse_vault_lock(docs[DOC_INDEX])

    if errors:
        for e in errors:
            print("FAIL:", e)
        print(
            "KETERANGAN: artefak tidak cocok dengan grammar mega-sdd — kalau ini "
            "file hasil tulis eksternal, itu bukan bug: grammar-nya memang belum "
            "diadopsi; cek lane adopsi: scripts/certify-artifact.sh --rung=vault "
            "menawarkan DEMOTE (re-ingest rung PRD) atau perbaiki manual mengikuti "
            "template vault generate-intent, atau re-generate via pipeline."
        )
        sys.exit(2)

    # ── 3. Cross-count guard (anti-silent-empty; independent loose parse) ──
    loose = {
        "entities": len(re.findall(r"^[Tt]able\s+\w",
                                   docs.get(DOC_DM, ""), re.M)),
        "flows": len(re.findall(r"^###\s+F-", docs.get(DOC_FL, ""), re.M)),
        "adrs": len(re.findall(r"^###\s+D-", docs.get(DOC_DC, ""), re.M)),
    }
    loose_oq_tags = set()
    for fn in OQ_DOCS:
        for line in docs.get(fn, "").splitlines():
            if re.match(r"^-\s*\[", line):
                m = vault_md.OQ_TAG_RE.search(line)
                if m:
                    loose_oq_tags.add(m.group(0))
    parsed = {"entities": len(entities), "flows": len(flows),
              "adrs": len(adrs), "oqs": len(skeletons)}
    loose["oqs"] = len(loose_oq_tags)
    for cls in ("entities", "flows", "adrs", "oqs"):
        if abs(parsed[cls] - loose[cls]) > 2:
            print(f"FAIL: cross-count guard tripped on {cls} — loose count "
                  f"{loose[cls]} vs parsed {parsed[cls]} (delta > 2). The md "
                  f"grammar the deriver reads diverges from the loose scan — "
                  f"fix the markdown structure, never hand-edit vault.json.")
            print(
                "KETERANGAN: artefak tidak cocok dengan grammar mega-sdd — kalau "
                "ini file hasil tulis eksternal, itu bukan bug: grammar-nya memang "
                "belum diadopsi; cek lane adopsi: scripts/certify-artifact.sh "
                "--rung=vault menawarkan DEMOTE (re-ingest rung PRD) atau perbaiki "
                "manual mengikuti template vault generate-intent, atau re-generate "
                "via pipeline."
            )
            sys.exit(2)

    # ── 4. Prior + patch + event (validation before any assembly) ──
    prior = {}
    if os.path.isfile(js_path):
        try:
            prior = json.load(open(js_path, encoding="utf-8"))
        except Exception as e:
            print(f"FAIL: prior vault.json unparseable ({e}) — refusing to "
                  f"clobber the carry-forward source; fix or remove it and re-run.")
            sys.exit(2)
        if not isinstance(prior, dict):
            print("FAIL: prior vault.json is not a JSON object")
            sys.exit(2)

    patch = {}
    if patch_path:
        try:
            patch = json.load(open(patch_path, encoding="utf-8"))
        except Exception as e:
            print(f"FAIL: --patch is not valid JSON ({e})")
            sys.exit(2)
        if not isinstance(patch, dict):
            print("FAIL: --patch must be a JSON object")
            sys.exit(2)

    event = None
    if event_raw:
        try:
            event = json.loads(event_raw)
        except Exception as e:
            print(f"FAIL: --event is not valid JSON ({e})")
            sys.exit(2)
        if not isinstance(event, dict) or "event" not in event:
            print("FAIL: --event must be a JSON object containing an 'event' key")
            sys.exit(2)

    prior_oqs = [e for e in (prior.get("open_questions") or [])
                 if isinstance(e, dict)]
    prior_by_tag = {}
    for e in prior_oqs:
        t = e.get("tag") or e.get("id")
        if t:
            prior_by_tag[t] = e
    skeleton_tags = {oq["tag"] for oq in skeletons}

    for k in patch:
        if k == "open_questions":
            continue
        if k in DERIVED_TOP:
            print(f"FAIL: --patch sets derived key '{k}' — the markdown is the "
                  f"single grammar; edit the vault docs and re-run (anti-laundering).")
            sys.exit(2)
    patch_oqs = patch.get("open_questions") or {}
    if patch_oqs and not isinstance(patch_oqs, dict):
        print("FAIL: --patch open_questions must be an object keyed by OQ tag")

