import '@testing-library/jest-dom/vitest'

import { afterAll, afterEach, beforeAll, vi } from 'vitest'

import type * as NextAuthReact from 'next-auth/react'

import { server } from './handlers'

const ORIGIN = 'http://localhost:3000'

// ── next/navigation ─────────────────────────────────────────────────────────
vi.mock('next/navigation', async () => {
  const { router } = await import('./mocks')

  return {
    useRouter: () => router,
    usePathname: () => '/',
    useSearchParams: () => new URLSearchParams(),
    useParams: () => ({}),
    redirect: vi.fn(),
    notFound: vi.fn()
  }
})

// ── next-auth/react ─────────────────────────────────────────────────────────
// RBAC hooks call useSession(); getSession() is stubbed for parity. Both read the
// live session from mocks.sessionState so tests can swap it with setMockSession().
vi.mock('next-auth/react', async () => {
  const actual = await vi.importActual<typeof NextAuthReact>('next-auth/react')
  const { sessionState } = await import('./mocks')

  return {
    ...actual,
    getSession: vi.fn(async () => sessionState.current),
    useSession: vi.fn(() => ({ data: sessionState.current, status: 'authenticated', update: vi.fn() })),
    SessionProvider: ({ children }: { children: React.ReactNode }) => children
  }
})

// ── jsdom polyfills MUI relies on ───────────────────────────────────────────
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: (query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn()
  })
})

class ResizeObserverStub {
  observe() {}
  unobserve() {}
  disconnect() {}
}

globalThis.ResizeObserver = ResizeObserverStub as unknown as typeof ResizeObserver

// ── MSW lifecycle + relative-URL fetch shim ─────────────────────────────────
beforeAll(() => {
  server.listen({ onUnhandledRequest: 'warn' })

  // undici (Node fetch) cannot parse relative URLs; apiClient targets '/api/...'.
  // Wrap the MSW-patched fetch so relative paths resolve against the test origin.
  const patched = globalThis.fetch

  globalThis.fetch = ((input: RequestInfo | URL, init?: RequestInit) => {
    if (typeof input === 'string' && input.startsWith('/')) {
      return patched(`${ORIGIN}${input}`, init)
    }

    return patched(input, init)
  }) as typeof fetch
})

afterEach(() => server.resetHandlers())
afterAll(() => server.close())
import { setupServer } from 'msw/node'
import { http, HttpResponse } from 'msw'

const ORIGIN = 'http://localhost:3000'

const envelope = <T>(data: T, total = Array.isArray(data) ? data.length : 1) => ({
  success: true,
  code: 'OK',
  message: 'ok',
  data,
  meta: { pagination: { total_rows: total } }
})

/**
 * Default MSW handlers for the access-control features shipped with the starter
 * kit. Individual tests override these per-case with `server.use(...)`.
 *
 * apiClient targets the same-origin proxy routes (`/api/v1/...`), so handlers are
 * registered against those paths; the fetch shim in setup.ts prefixes relative
 * URLs with ORIGIN.
 */
export const handlers = [
  http.get(`${ORIGIN}/api/v1/users`, () =>
    HttpResponse.json(
      envelope([
        {
          id: 'u1',
          username: 'jdoe',
          fullName: 'John Doe',
          email: 'jdoe@example.com',
          isActive: true
        }
      ])
    )
  ),

  http.get(`${ORIGIN}/api/v1/users/:id`, ({ params }) =>
    HttpResponse.json(
      envelope({
        id: String(params.id),
        username: 'jdoe',
        fullName: 'John Doe',
        email: 'jdoe@example.com',
        isActive: true
      })
    )
  ),

  http.post(`${ORIGIN}/api/v1/users`, async ({ request }) => {
    const body = (await request.json()) as Record<string, unknown>

    return HttpResponse.json(envelope({ id: 'new-user', ...body }))
  }),

  http.put(`${ORIGIN}/api/v1/users/:id`, async ({ request, params }) => {
    const body = (await request.json()) as Record<string, unknown>

    return HttpResponse.json(envelope({ id: params.id, ...body }))
  }),

  http.delete(`${ORIGIN}/api/v1/users/:id`, ({ params }) => HttpResponse.json(envelope({ id: params.id }))),

  http.get(`${ORIGIN}/api/v1/roles`, () => HttpResponse.json(envelope([{ id: 'r1', name: 'Admin', permissions: [] }]))),

  http.get(`${ORIGIN}/api/v1/permission`, () =>
    HttpResponse.json(envelope([{ id: 'p1', name: 'USER.READ', resource: 'USER', action: 'READ' }]))
  ),

  http.get(`${ORIGIN}/api/v1/branches`, () => HttpResponse.json(envelope([{ id: 'b1', code: '001', name: 'Head Office' }])))
]

export const server = setupServer(...handlers)
import type { ReactElement, ReactNode } from 'react'

import { render, type RenderOptions } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { SnackbarProvider } from 'notistack'

/**
 * Fresh QueryClient per render with retries off and caching disabled so tests are
 * deterministic and isolated.
 */
function makeQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0, staleTime: 0 },
      mutations: { retry: false }
    }
  })
}

function AllProviders({ children }: { children: ReactNode }) {
  const queryClient = makeQueryClient()

  return (
    <QueryClientProvider client={queryClient}>
      <SnackbarProvider maxSnack={3}>{children}</SnackbarProvider>
    </QueryClientProvider>
  )
}

/**
 * Render a component inside the app's runtime providers (Query + Snackbar).
 * next/navigation and next-auth/react are already mocked globally in setup.ts.
 * Returns a configured `user` (userEvent) alongside the usual RTL result.
 */
export function renderWithProviders(ui: ReactElement, options?: Omit<RenderOptions, 'wrapper'>) {
  return {
    user: userEvent.setup(),
    ...render(ui, { wrapper: AllProviders, ...options })
  }
}

export * from '@testing-library/react'
export { userEvent }
import { describe, expect, it } from 'vitest'

import { renderWithProviders, screen } from './utils'

// Sanity check that the harness (jsdom + RTL + providers + jest-dom matchers) wires up.
describe('test harness smoke', () => {
  it('renders a component through providers', () => {
    renderWithProviders(<button type='button'>Hello</button>)
    expect(screen.getByRole('button', { name: 'Hello' })).toBeInTheDocument()
  })

  it('intercepts fetch via MSW with the relative-URL shim', async () => {
    const res = await fetch('/api/v1/users')
    const json = await res.json()

    expect(json.success).toBe(true)
    expect(json.data).toHaveLength(1)
  })
})
import { vi } from 'vitest'

import type { Session } from 'next-auth'

/**
 * Shared mock state for next/navigation and next-auth/react.
 *
 * These are referenced from the `vi.mock(...)` factories in `setup.ts` (which run
 * once per test file). Tests import these to assert against `router.push` or to
 * swap the active session via `setMockSession`.
 */

export const router = {
  push: vi.fn(),
  replace: vi.fn(),
  refresh: vi.fn(),
  back: vi.fn(),
  forward: vi.fn(),
  prefetch: vi.fn()
}

// Super-admin by default so feature tests aren't blocked by RBAC. Tests that care
// about gating should call setMockSession() with an explicit permission list.
const defaultSession = {
  accessToken: 'test-access-token',
  user: {
    id: 'u1',
    username: 'testuser',
    fullName: 'Test User',
    email: 'test@example.com',
    roles: ['admin'],
    permissions: ['*']
  },
  expires: '2099-01-01T00:00:00.000Z'
} as unknown as Session

// Mutable holder so the next-auth/react mock can read the current session live.
export const sessionState: { current: Session | null } = { current: defaultSession }

export function setMockSession(session: Session | null) {
  sessionState.current = session
}

export function resetMockSession() {
  sessionState.current = defaultSession
}

