/**
 * Shared mock state for next/navigation and next-auth/react.
 *
 * These are referenced from the `vi.mock(...)` factories in `setup.ts` (which run
 * once per test file). Tests import these to assert against `router.push` or to
 * swap the active session via `setMockSession`.
