// Browser fetcher. Calls the same-origin Next.js proxy routes under /api/v1/**
// (BASEPATH-aware via NEXT_PUBLIC_BASEPATH). It sends NO Authorization header —
// the httpOnly next-auth session cookie travels with the same-origin request and
// the proxy route attaches the bearer to the upstream call server-side. Throws on
// non-OK so mutation hooks surface the message via onError.
const BASE_PATH = process.env.NEXT_PUBLIC_BASEPATH ?? ''

export const apiClient = createFetcher({
