'use client'

import { useMutation, useQueryClient, type QueryKey } from '@tanstack/react-query'

import { enqueueSnackbar } from 'notistack'

/**
 * Factories for the create/update/delete mutation hooks duplicated across every
 * feature (snackbar on success/error + query invalidation). Usage:
 *
 *   export const useCreateUser = makeCreateMutation({
 *     mutationFn: createUser, listKey: userKeys.lists(), successMessage: 'User created'
 *   })
 *
 * The returned closures are named `use*` so eslint-plugin-react-hooks treats them
 * as hooks.
 */

type WithId = { id: string }

export function makeCreateMutation<TData, TVars>(config: {
  mutationFn: (vars: TVars) => Promise<TData>
  listKey: QueryKey
  successMessage: string
}) {
  return function useCreateMutation() {
    const qc = useQueryClient()

    return useMutation({
      mutationFn: config.mutationFn,
      onSuccess: () => {
        enqueueSnackbar(config.successMessage, { variant: 'success' })
        qc.invalidateQueries({ queryKey: config.listKey })
      },
      onError: (err: Error) => enqueueSnackbar(err.message, { variant: 'error' })
    })
  }
}

export function makeUpdateMutation<TData, TVars extends WithId>(config: {
  mutationFn: (vars: TVars) => Promise<TData>
  listKey: QueryKey
  detailKey: (id: string) => QueryKey
  successMessage: string
}) {
  return function useUpdateMutation() {
    const qc = useQueryClient()

    return useMutation({
      mutationFn: config.mutationFn,
      onSuccess: async (_data, vars) => {
        enqueueSnackbar(config.successMessage, { variant: 'success' })
        await Promise.all([
          qc.invalidateQueries({ queryKey: config.listKey }),
          qc.invalidateQueries({ queryKey: config.detailKey(vars.id) })
        ])
      },
      onError: (err: Error) => enqueueSnackbar(err.message, { variant: 'error' })
    })
  }
}

export function makeDeleteMutation<TData, TVars extends WithId>(config: {
  mutationFn: (vars: TVars) => Promise<TData>
  listKey: QueryKey
  detailKey: (id: string) => QueryKey
  successMessage: string
}) {
  return function useDeleteMutation() {
    const qc = useQueryClient()

    return useMutation({
      mutationFn: config.mutationFn,
      onSuccess: async (_data, vars) => {
        enqueueSnackbar(config.successMessage, { variant: 'success' })
        await Promise.all([
          qc.invalidateQueries({ queryKey: config.listKey }),
          qc.removeQueries({ queryKey: config.detailKey(vars.id) })
        ])
      },
      onError: (err: Error) => enqueueSnackbar(err.message, { variant: 'error' })
    })
  }
}
