def parse_prd_source_refs(fm):
    """`prd_source:` scalar, flow list `[a, b]`, or block list → raw refs (quotes stripped)."""
    m = re.search(r"^prd_source:[ \t]*(.*)$", fm, re.MULTILINE)
    if not m:
        return []
    head = m.group(1).strip()
    if head.startswith("["):
        return [x.strip().strip("'\"") for x in head.strip("[]").split(",") if x.strip()]
    if head:
        return [head.strip("'\"")]
    refs = []
    for ln in fm[m.end():].splitlines():
        if re.match(r"^\s*-\s+", ln):
            refs.append(re.sub(r"^\s*-\s+", "", ln).strip().strip("'\""))
        elif ln.strip() == "":
            continue
        else:
            break
    return refs


def _slug(text):
    return re.sub(r"-+", "-", re.sub(r"[^a-z0-9]+", "-", text.strip().lower())).strip("-")


def resolve_prd_source(ref):
    m = PRD_REF_RE.match(ref.strip())
    if not m:
        return False, "shape must be <prd-file>.md#<heading-slug> or <prd-file>.md:<line>"
    path = os.path.join(cwd, m.group("file"))
    if not os.path.isfile(path):
        return False, f"file not found under project root: {m.group('file')}"
    try:
        text = open(path, encoding="utf-8", errors="replace").read()
    except OSError as e:
        return False, f"unreadable: {e}"
    if m.group("line"):
        n = int(m.group("line")); total = text.count("\n") + 1
        return (1 <= n <= total), ("" if 1 <= n <= total else f"line {n} outside 1..{total}")
    want = _slug(m.group("slug"))
    heads = [_slug(h) for h in re.findall(r"^#{1,6}[ \t]+(.+?)\s*$", text, re.MULTILINE)]
    if want in heads:
        return True, ""
    return False, f"no heading with slug '{want}' (have: {', '.join(heads[:8])}{'…' if len(heads) > 8 else ''})"


def vault_source_shape(value):
    v = value.strip()
    if re.fullmatch(VS_DOC_RE + r"#\S+", v):
        return "canonical"
    if re.fullmatch(VS_DOC_RE, v):
        return "no_anchor"
    if re.fullmatch(VS_DOC_RE + r":\S+", v):
        return "legacy_colon_separator"
    if re.fullmatch(VS_DOC_RE + r"\s*§\s*.+", v):
        return "legacy_section_sign"
    if re.match(VS_DOC_RE + r"\b", v):
        return "malformed_anchor"
    return "unknown_doc"


def validate_unit(file_path):
    """All unit-spec checks for ONE unit file. Returns the issue list (each issue
    tagged with the unit's repo-relative path)."""
    issues = []
    rel_path = os.path.relpath(file_path, cwd)
    try:
        body = open(file_path, errors="replace").read()
    except Exception as e:
        return [{"halt_type": "unit_underspecified", "file": rel_path,
                 "detail": f"cannot read unit file: {e}"}]

    # Extract frontmatter
    fm_match = re.match(r"^---\n(.*?)\n---\n?", body, re.DOTALL)
    if not fm_match:
        return [{"halt_type": "unit_underspecified", "file": rel_path,
                 "detail": "unit has no frontmatter YAML block (--- ... ---)",
                 "missing_fields": ["entire_frontmatter"]}]

    fm = fm_match.group(1)
    body_after_fm = body[fm_match.end():]

    # ─── Check 1: unit_underspecified — required frontmatter fields ──────────
    # Accept either Layout A (unit_id) or Layout B (id) for unit identifier.
    field_present = {}
    for f in ["unit_id", "id", "title", "task_type", "target_files", "vault_source", "vault_anchors", "context_source"]:
        if re.search(rf"^{f}:", fm, re.MULTILINE):
            field_present[f] = True

    unit_id = None
    m = re.search(r"^(?:unit_id|id):\s*(\S+)", fm, re.MULTILINE)
    if m: unit_id = m.group(1)
    if not unit_id:
        if os.path.basename(file_path) == "unit.md":
            unit_id = os.path.basename(os.path.dirname(file_path))
        else:
            unit_id = os.path.basename(file_path).replace(".md", "")

    # ─── vault_source grammar (v8 P0, 2026-09-10) — ADVISORY, never an issue ──
    # ONE canonical form: `<doc>.md#<anchor>` (unit-schema.md §Required
    # frontmatter). Field + fixture units carry four shapes today (`doc#anchor`,
    # `doc:anchor`, `doc §anchor`, bare `doc`), every deterministic reader is
    # anchor-agnostic (F_ID_RE.search), and no gate keys on the value — so this
    # records the drift in the state's top-level `vault_source_advisory` list
    # (precedent: hard_rules_directive_advisory) and NEVER touches `issues`,
    # `status` or the exit code. Muatan, bukan bukti: a new hard gate here would
    # freeze every existing project over a separator.
    # ─── prd_source (v8 P1, spec App. F1a) — RESOLVED when present, never required ─
    # `<prd-file>#<heading-slug>` or `<prd-file>:<line>`, scalar or YAML list. A
    # citation to a heading/line that does not exist is a fabricated requirement
    # → issue prd_source_unresolvable (status FAIL for generate-units Step 12 /
    # analyze; NOT a hook gate). Absent field = legacy unit, silent.
    for ref in parse_prd_source_refs(fm):
        ok, why = resolve_prd_source(ref)
        if not ok:
            issues.append({"halt_type": "prd_source_unresolvable",
                           "detail": f"unit {unit_id} prd_source {ref!r} does not resolve: {why}",
                           "unit_id": unit_id, "prd_source": ref, "reason": why})

    vs_m = re.search(r"^(?:vault_source|context_source):\s*(.+?)\s*$", fm, re.MULTILINE)
    if vs_m:
        vs_raw = vs_m.group(1).strip().strip("'\"")
        vs_shape = vault_source_shape(vs_raw)
        if vs_shape != "canonical":
            vs_adv.append({"unit_id": unit_id, "file": rel_path,
                           "vault_source": vs_raw, "shape": vs_shape,
                           "canonical_form": "<doc>.md#<anchor>"})

    _xs_over = xs_body_over(fm, body_after_fm)
    if _xs_over:
        xs_adv.append({"unit_id": unit_id, "file": rel_path, "over": _xs_over,
                       "budget": "xs class (acceptance 1..2, steps 1..3): Goal 1 line · Context <= 2 sentences · Anti-patterns/Out of scope only with a source per item"})

    # S5 GU-TASKTYPE-ENUM-1: tolerate quoted scalars + normalize case, then
    # validate against the CLOSED enum — an unknown value is flagged, never
    # silently skipped past every per-type rail.
    task_type_match = re.search(r"^task_type:\s*[\"']?([A-Za-z_-]+)[\"']?", fm, re.MULTILINE)
    task_type_raw = task_type_match.group(1) if task_type_match else None
    task_type = task_type_raw.strip().lower() if task_type_raw else None
    if task_type is not None and task_type not in VALID_TASK_TYPES:
        issues.append({
            "halt_type": "unit_underspecified",
            "detail": (f"unit {unit_id} has invalid task_type '{task_type_raw}' — "
                       f"must be one of create|verify|extend (closed enum)"),
            "unit_id": unit_id,
            "task_type": task_type_raw,
            "invalid_fields": ["task_type"],
        })

    # Required fields (lenient: accept unit_id OR id)
    missing_fields = []
    if "unit_id" not in field_present and "id" not in field_present:
        missing_fields.append("unit_id|id")
    if "title" not in field_present:
        missing_fields.append("title")
    if "task_type" not in field_present:
        missing_fields.append("task_type")
    # vault_source OR vault_anchors (layout B uses vault_anchors)
    if "vault_source" not in field_present and "vault_anchors" not in field_present and "context_source" not in field_present:
        missing_fields.append("vault_source|context_source|vault_anchors")
    # target_files presence (for verify, may be empty list; for create/extend, must have entries)
    if "target_files" not in field_present:
        missing_fields.append("target_files")

    if missing_fields:
        issues.append({
            "halt_type": "unit_underspecified",
            "detail": f"unit {unit_id} frontmatter missing required field(s): {missing_fields}",
            "unit_id": unit_id,
            "task_type": task_type,
            "missing_fields": missing_fields,
        })

    # S5 GU-VUS-AT-PRESENCE-1: acceptance_test presence (schema rail: every unit
    # MUST carry one — "No exceptions"). Structured key in frontmatter or body;
    # an empty list does not count. Detection-layer (not a PreToolUse gate read).
    at_m = re.search(r"^acceptance_test\s*:\s*(.*?)(?=^\S|\Z)", body, re.DOTALL | re.MULTILINE)
    at_region = at_m.group(1).strip() if at_m else ""
    if not at_m or not at_region or at_region in ("[]", "[ ]", "null", "~"):
        issues.append({
            "halt_type": "unit_underspecified",
            "detail": (f"unit {unit_id} has no non-empty `acceptance_test:` entry — every unit "
                       f"MUST carry one (unit-schema §acceptance_test, no exceptions)"),
            "unit_id": unit_id,
            "task_type": task_type,
            "missing_fields": ["acceptance_test"],
        })

    # ─── Check: acceptance_path_unowned (spec 2026-08-29 Fase 4) ──────────────
    # Field defect this closes: a unit whose acceptance_test command runs a file
    # that is in NO unit's target_files. Every branch then violates an Iron Rule
    # — committing the file trips B3 whitelist_violation, skipping it fails the
    # acceptance command — so the unit is unfinishable by construction and the
    # implementer only discovers it after a full dispatch has burned.
    #
    # Conservative by design (this gate BLOCKS): a token is only reported when
    # it is path-shaped AND declared by no unit AND absent from disk AND not a
    # B3 sanctioned extra. A path that already exists is pre-existing input; a
    # path a sibling unit declares is owned by the DAG; a TEST path is written
    # and committed by the implementer and B3 sanctions it precisely because
    # "units often do not list it". All three are silent.
    #
    # SANCTIONED_RX MUST stay byte-identical to the B3 predicate in
    # scripts/validate-bolt-artifacts.sh (§whitelist scan) — if this check is
    # stricter than the observer it gates on, it blocks the normal convention.
    # That divergence is exactly the 2026-08-29 field defect, from the other
    # side: the implementer contract omitted these extras and a bolt halted
    # with scope_creep_detected over a test file B3 would never have flagged.
    # Pinned by tests/acceptance-path/ (drift tripwire).
    at_cmds = re.findall(r"(?m)^\s*(?:-\s*)?command:\s*(?:\"([^\"]*)\"|'([^']*)'|(.+?))\s*$", body)
    unowned = []
    for tup in at_cmds:
        cmd = next((x for x in tup if x), "")
        for tok_raw in cmd.split():
            tok = tok_raw.strip("\"'`,;()")
            if "=" in tok and not tok.startswith("/"):
                tok = tok.split("=", 1)[1].strip("\"'")   # --config=path/to/x.json
            if not tok or tok.startswith("-") or tok.startswith("@"):
                continue
            if "/" not in tok or "://" in tok or tok.startswith("/"):
                continue
            if any(ch in tok for ch in "*?[]{}$"):
                continue                                   # a glob declares nothing
            if not re.search(r"\.[A-Za-z0-9]{1,6}$", tok):
                continue                                   # directories are not files
            norm = tok.lstrip("./")
            if norm.split("/")[0] in ("node_modules", "vendor", "dist", "build", ".mega-sdd"):
                continue
            if norm in OWNED_PATHS:
                continue
            if re.search(SANCTIONED_RX, norm):
                continue                                   # B3 sanctioned extra
            if os.path.exists(os.path.join(cwd, norm)):
                continue                                   # pre-existing input
            unowned.append(norm)
    # ─── Check: acceptance_expects_missing (F-18, spec 2026-08-30 §3.3) ──────
    # `run-acceptance-tests.sh` passes an entry on rc==0 AND (expects empty OR
    # expects in output) — an empty `expects` makes the second term vacuous, so
    # B4 measures only the exit code of a test the same model wrote (69/69
    # entries on the field run; acceptance never observed a failure). A
    # command-bearing `type: test` entry (or untyped) MUST name the substring the
    # output proves. Exempt: manual (never executed) and render (route-200 +
    # display assertion — its command IS the proof). Gated PER UNIT at dispatch
    # by the in-run aggregator (never at the run boundary — no retro-freeze).
    try:
        _ftext = open(file_path, encoding="utf-8", errors="replace").read()
    except OSError:
        _ftext = ""
    _at = re.search(r"^acceptance_test\s*:\s*(.*?)(?=^\S|\Z)", _ftext, re.DOTALL | re.MULTILINE)
    _vacuous = []
    if _at:
        _cur = None; _ents = []
        for _ln in _at.group(1).splitlines():
            if re.match(r"^\s*-\s", _ln):
                if _cur: _ents.append(_cur)
                _cur = {}; _ln = re.sub(r"^\s*-\s*", "", _ln)
            if _cur is None: continue
            _m = re.match(r"^\s*([A-Za-z_]+)\s*:\s*(.*)$", _ln)
            if _m:
                _k = _m.group(1).strip().lower(); _v = _m.group(2).strip().strip("'\"")
                if _k in ("type", "kind", "command", "expects"):
                    _cur.setdefault("type" if _k == "kind" else _k, _v)
        if _cur: _ents.append(_cur)
        for _e in _ents:
            _t = (_e.get("type") or "test").lower()
            if _t in ("test",) and _e.get("command") and not _e.get("expects"):
                _vacuous.append(_e["command"][:120])
    if _vacuous:
        issues.append({
            "halt_type": "acceptance_expects_missing",
            "detail": (f"unit {unit_id} has {len(_vacuous)} acceptance_test `type: test` "
                       f"entr{'y' if len(_vacuous)==1 else 'ies'} with a command but NO `expects` — "
                       f"the B4 gate then measures only rc==0 of a test the implementer wrote "
                       f"(vacuous). Add `expects: \"<substring the output must contain>\"` "
                       f"(e.g. the runner's pass line) to each entry, then re-dispatch."),
            "unit_id": unit_id,
            "task_type": task_type,
            "commands": _vacuous,
        })

    if unowned:
        issues.append({
            "halt_type": "acceptance_path_unowned",
            "detail": (f"unit {unit_id} runs acceptance_test command(s) against "
                       f"{sorted(set(unowned))} — no unit declares these in target_files "
                       f"and they do not exist. The unit cannot be completed: committing "
                       f"the file trips the B3 whitelist observer, skipping it fails the "
                       f"acceptance command. Add the path to this unit's target_files "
                       f"(operation: create), or point the command at a path a unit owns."),
            "unit_id": unit_id,
            "task_type": task_type,
            "unowned_paths": sorted(set(unowned)),
        })

    # ─── Per-task_type section contracts (S5 GU-TTCONTRACT-1: content, not just
    # heading presence — an empty `## Anchors`/`## Migration notes` carried no
    # payload for the bolt; a create unit WITH Migration notes signals a
    # mis-assigned task_type per 12.5.d) ───────────────────────────────────────

