7	// Your API endpoint that returns JWT (for future use)
8	const API_URL = process.env.NEXT_PUBLIC_API_URL || 'https://api.yourdomain.com'
9	
10	// Helpers
11	async function refreshAccessToken(token: JWT): Promise<JWT> {
12	  try {
13	    const res = await fetch(`${API_URL}/auth/refresh`, {
14	      method: 'POST',
15	      headers: { 'Content-Type': 'application/json' },
16	      body: JSON.stringify({ refreshToken: token.refreshToken })
17	    })
18	
19	    if (!res.ok) throw new Error('Refresh failed')
20	
21	    const data: { data: RefreshToken } = await res.json()
22	
23	    return {
24	      ...token,
25	      accessToken: data.data.accessToken,
26	      refreshToken: data.data.refreshToken ?? token.refreshToken,
27	      expiresIn: data.data.expiresIn,
28	      error: undefined // clear any previous error
29	    }
30	  } catch {
31	    // Refresh failed — signal the client to sign out
32	    return {
33	      ...token,
34	      error: 'RefreshTokenError'
35	    }
36	  }
37	}
