39	export const authOptions: NextAuthOptions = {
40	  session: {
41	    // Must outlive the upstream access token so refreshAccessToken() can run.
42	    // Set to the backend refresh-token TTL — shorter than this wastes the refresh flow.
43	    strategy: 'jwt',
44	    maxAge: 7 * 24 * 60 * 60 // 7 days
45	  },
46	  pages: {
47	    signIn: '/login',
48	    error: '/login'
49	  },
50	  providers: [
51	    CredentialsProvider({
52	      name: 'credentials',
53	      credentials: {
54	        username: { label: 'Username', type: 'text' },
55	        password: { label: 'Password', type: 'password' }
56	      },
57	      async authorize(credentials) {
58	        if (!credentials?.username || !credentials?.password) {
59	          throw new Error('Invalid credentials')
60	        }
61	
62	        const response = await fetch(`${API_URL}/auth/login`, {
63	          method: 'POST',
64	          headers: { 'Content-Type': 'application/json' },
65	          body: JSON.stringify({
66	            username: credentials.username,
67	            password: credentials.password
68	          })
69	        })
70	
71	        if (!response.ok) {
72	          const errorData = await response.json().catch(() => null)
73	          const message = errorData?.message || errorData?.error || 'Invalid credentials'
74	
75	          throw new Error(message)
76	        }
77	
78	        const data: { data: LoginResponseData } = await response.json()
79	        const { user, accessToken, refreshToken, expiresIn, roles, permissions } = data.data
80	
81	        if (!accessToken) {
82	          throw new Error('No token received')
83	        }
84	
85	        return {
86	          id: user.userId,
87	          username: user.username,
88	          email: user.userEmail,
89	          fullName: user.userFullName,
90	          roles,
91	          permissions,
92	          accessToken,
93	          refreshToken,
94	          expiresIn
95	        }
96	      }
97	    })
98	  ],
99	  callbacks: {
100	    async jwt({ token, user, trigger, session }): Promise<JWT> {
101	      // Initial sign in — store token + calculate exact expiry timestamp
102	      if (user) {
103	        return {
104	          ...token,
105	          id: user.id,
106	          email: user.email,
107	          username: user.username,
108	          fullName: user.fullName,
109	          roles: user.roles,
110	          permissions: user.permissions,
111	          accessToken: user.accessToken,
112	          refreshToken: user.refreshToken,
113	
114	          // Store the absolute expiry time in ms
115	          expiresIn: user.expiresIn
116	        }
117	      }
118	
119	      // Handle manual session update
120	      if (trigger === 'update' && session) {
121	        return { ...token, ...session }
122	      }
123	
124	      // token.expiresIn is an absolute ms timestamp (matches API's `expiresIn`
125	      // field, which is unix-ms, not a duration). Compare against Date.now() directly.
126	      if (Date.now() < token.expiresIn) {
127	        return token
128	      }
129	
130	      //Token expired — attempt refresh
131	      return refreshAccessToken(token)
132	    },
133	
134	    async session({ session, token }) {
135	      // Surface the error to the client so it can force sign out
136	      if (token.error) {
137	        session.error = token.error
138	      }
139	
140	      if (token && session.user) {
141	        session.user.id = token.id
142	        session.user.email = token.email
143	        session.user.username = token.username
144	        session.user.fullName = token.fullName
145	        session.user.roles = token.roles
146	        session.user.permissions = token.permissions
147	        session.accessToken = token.accessToken!
148	        session.expiresIn = token.expiresIn
149	      }
150	
151	      return session
152	    }
