1	import { NextResponse, type NextRequest } from 'next/server'
2	
3	import { apiServer } from './server'
4	import type { ApiResponse } from '@/types/common'
5	
6	/**
7	 * Thin-proxy route-handler factory. Collapses the repeated
8	 * `try { const res = await apiServer.x(...); return NextResponse.json(...) } catch {...}`
9	 * boilerplate in `src/app/api/**` into one-liners that forward to the upstream API
10	 * via apiServer and return its envelope verbatim, mapping a failed envelope to a
11	 * 4xx so apiClient's throw-on-!ok behavior keeps working.
12	 *
13	 * `buildPath` is either a static upstream path or a function of the dynamic route
14	 * params (e.g. `({ id }) => `/v1/users/${id}``).
15	 */
16	type Ctx<P> = { params: Promise<P> }
17	type PathBuilder<P> = string | ((params: P) => string)
18	
19	function respond<T>(res: ApiResponse<T>) {
20	  return NextResponse.json(res, { status: res.success === false ? 400 : 200 })
21	}
22	
23	function resolvePath<P>(buildPath: PathBuilder<P>, params: P): string {
24	  return typeof buildPath === 'function' ? buildPath(params) : buildPath
25	}
26	
27	async function readParams<P>(ctx?: Ctx<P>): Promise<P> {
28	  return ctx?.params ? await ctx.params : ({} as P)
29	}
30	
31	export function proxyGet<T, P = Record<string, string>>(
32	  buildPath: PathBuilder<P>,
33	  options: { forwardQuery?: boolean } = {}
34	) {
35	  return async (req: NextRequest, ctx?: Ctx<P>) => {
36	    const params = await readParams(ctx)
37	    const query = options.forwardQuery ? Object.fromEntries(new URL(req.url).searchParams) : undefined
38	
39	    return respond(await apiServer.get<T>(resolvePath(buildPath, params), { params: query }))
40	  }
41	}
42	
43	export function proxyPost<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
44	  return async (req: NextRequest, ctx?: Ctx<P>) => {
45	    const params = await readParams(ctx)
46	    const body = await req.json()
47	
48	    return respond(await apiServer.post<T>(resolvePath(buildPath, params), body))
49	  }
50	}
51	
52	export function proxyPut<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
53	  return async (req: NextRequest, ctx?: Ctx<P>) => {
54	    const params = await readParams(ctx)
55	    const body = await req.json()
56	
57	    return respond(await apiServer.put<T>(resolvePath(buildPath, params), body))
58	  }
59	}
60	
61	export function proxyDelete<T, P = Record<string, string>>(buildPath: PathBuilder<P>) {
62	  return async (_req: NextRequest, ctx?: Ctx<P>) => {
63	    const params = await readParams(ctx)
64	
65	    return respond(await apiServer.delete<T>(resolvePath(buildPath, params)))
66	  }
67	}
