// Company-profile pages that anyone may open without signing in. Kept apart from
// the login/register list in the route guard, because that list also bounces
// signed-in users to /home — these pages must stay reachable for everyone.
export const PUBLIC_PAGE_ROUTES = ['/beranda', '/tentang-kami', '/kontak'] as const

export type PublicPageRoute = (typeof PUBLIC_PAGE_ROUTES)[number]

// Exact match only: look-alikes (/kontakx) and nested paths (/kontak/detail) are not public.
export function isPublicPageRoute(pathname: string): pathname is PublicPageRoute {
  return (PUBLIC_PAGE_ROUTES as readonly string[]).includes(pathname)
}

