import { NextResponse, type NextRequest } from 'next/server'

import { z } from 'zod'

import { apiServer } from '@/libs/api/server'
import { contactMessageSchema } from '@/features/company-profile/schemas/contact-message'

/**
 * Public contact-form endpoint. Unlike the one-line `proxyPost` routes, this
 * handler validates the body on the server first and forwards only the parsed
 * `name` / `email` / `message` upstream — the raw body never reaches the API,
 * and the upstream store stamps `created_at` itself.
 */
export async function POST(req: NextRequest) {
  // A body that is not valid JSON is treated as a validation failure.
  const body: unknown = await req.json().catch(() => undefined)
  const parsed = contactMessageSchema.safeParse(body)

  if (!parsed.success) {
    return NextResponse.json(
      {
        success: false,
        code: 'VALIDATION_ERROR',
        message: 'Validation failed',
        data: { errors: z.flattenError(parsed.error).fieldErrors }
      },
      { status: 400 }
    )
  }

  const res = await apiServer.post('/v1/contact-messages', parsed.data)

  return NextResponse.json(res, { status: res.success === false ? 400 : 200 })
}

