import { http, HttpResponse } from 'msw'
import { NextRequest } from 'next/server'
import { describe, expect, it, vi } from 'vitest'

import { server } from '@/test/handlers'

import { POST } from './route'

// The contact endpoint is public: apiServer must forward without a session.
vi.mock('next-auth', () => ({ getServerSession: vi.fn(async () => null) }))

const UPSTREAM = 'http://localhost:3000/v1/contact-messages'

const successEnvelope = { success: true, code: 'OK', message: 'Message received', data: { id: 'cm-1' } }

const valid = { name: 'Budi Santoso', email: 'budi@example.com', message: 'Halo, saya ingin bertanya.' }

function postRequest(body: string) {
  return new NextRequest('http://localhost:3000/api/v1/contact-messages', {
    method: 'POST',
    body,
    headers: { 'content-type': 'application/json' }
  })
}

// Registers an upstream handler that records every body it receives.
function recordUpstream(reply: () => Response = () => HttpResponse.json(successEnvelope)) {
  const bodies: unknown[] = []

  server.use(
    http.post(UPSTREAM, async ({ request }) => {
      bodies.push(await request.json())

      return reply()
    })
  )

  return bodies
}

describe('POST /api/v1/contact-messages', () => {
  it('returns 400 with field errors and does not call upstream for invalid input', async () => {
    const bodies = recordUpstream()

    const res = await POST(postRequest(JSON.stringify({ name: '', email: 'bukan-email', message: 'x'.repeat(2001) })))
    const json = await res.json()

    expect(res.status).toBe(400)
    expect(json.success).toBe(false)
    expect(json.code).toBe('VALIDATION_ERROR')
    expect(Object.keys(json.data.errors).sort()).toEqual(['email', 'message', 'name'])
    expect(json.data.errors.email.length).toBeGreaterThan(0)
    expect(bodies).toHaveLength(0)
  })

  it('forwards only name, email and message upstream for valid input', async () => {
    const bodies = recordUpstream()

    const res = await POST(
      postRequest(
        JSON.stringify({
          ...valid,
          name: '  Budi Santoso  ',
          id: 'injected',
          created_at: '1999-01-01T00:00:00Z',
          isAdmin: true
        })
      )
    )

    expect(res.status).toBe(200)
    expect(bodies).toEqual([valid])
  })

  it('returns 400 without calling upstream when the request body is not valid json', async () => {
    const bodies = recordUpstream()

    const res = await POST(postRequest('{"name": "Budi",'))
    const json = await res.json()

    expect(res.status).toBe(400)
    expect(json.success).toBe(false)
    expect(json.code).toBe('VALIDATION_ERROR')
    expect(bodies).toHaveLength(0)
  })

  it('maps an upstream failure envelope to a 400 response and returns 200 with the upstream envelope on success', async () => {
    recordUpstream(() =>
      HttpResponse.json({ success: false, code: 'UPSTREAM_ERROR', message: 'Storage unavailable', data: null }, { status: 503 })
    )

    const failed = await POST(postRequest(JSON.stringify(valid)))

    expect(failed.status).toBe(400)
    expect(await failed.json()).toEqual({
      success: false,
      code: 'UPSTREAM_ERROR',
      message: 'Storage unavailable',
      data: null
    })

    server.resetHandlers()
    recordUpstream()

    const succeeded = await POST(postRequest(JSON.stringify(valid)))

    expect(succeeded.status).toBe(200)
    expect(await succeeded.json()).toEqual(successEnvelope)
  })
})
